insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g4_fa_v1'
from (values
('117.114.b.1.A',3,'A student paints the school playground to share a memory with viewers. The idea came from...','["life experiences", "a spelling list", "a bus rule", "a weather chart"]'::jsonb,0,'Artists communicate ideas from life.','original'),
('117.114.b.1.A',3,'Painting a creature that is half bird and half fish comes from...','["a ruler", "imagination", "a map", "a textbook"]'::jsonb,1,'Imagination is a source for original art.','original'),
('117.114.b.1.B',3,'When an artist draws long curved marks that swirl across the paper, she is using the element of art called...','["math", "speech", "line", "rhythm in music"]'::jsonb,2,'Lines are an element of art.','original'),
('117.114.b.1.B',4,'A work where one side matches the other in weight and size shows...','["noise", "speed", "hunger", "balance"]'::jsonb,3,'Balance is a principle of design.','original'),
